INSERT OR REPLACE INTO notes (slug, category, title, content, parent_slug, sort_order, updated_at) VALUES ('基础电子元件库/三极管Bipolar Junction Transistor', 'synth', '三极管Bipolar Junction Transistor', '<h1>三极管Bipolar Junction Transistor</h1><div>一、三极管原理</div><div>三极管是重要的半导体元件，有时也把他叫做晶体管（transister），实际上它属于晶体管的子类，选择不同的三极管会很大程度上改变我们制造的声音，按照制造的材料来划分，三极管可以分为硅管和锗管，而按照导电方式来分，三极管可以分为PNP型和NPN型。</div><div><div contenteditable="false" data-resizable="" class="img-light selected" style="margin: 16px auto; resize: both; max-width: 100%; min-width: 40px; min-height: 20px; text-align: center; height: 272px; width: 186px;"><img src="data:image/png;base64," style="pointer-events: none;"></div>三极管的三极分别为基极、集电极和发射极。</div><div>二、三极管的挑选</div><div>三极管的型号命名规则比较混乱，比如2N开头的是美制标准的三极管，BC/BD/BF开头的是欧制标准，SA/SC开头的是日制标准，比较好的方式是对于一些常用的三极管，直接搜索相关参数，进行选择，下面介绍几个常用的三极管型号。</div><div><div>2N3904：一款NPN结构的通用普通型三极管，最大耐压为40V，放大系数范围在30至300之间。</div><div>2N3906：一款PNP结构的通用普通型三极管，最大耐压为40V，放大系数范围在30至300之间。</div><div>BC547：一款NPN结构的放大作用三极管，最大耐压为45V，放大系数范围在110至800之间。</div><div>MPSA13：一款NPN结构的高频放大作用三极管，最大耐压为30V，放大系数范围在100至250之间。</div><div>目前锗管因为不稳定在世界范围内基本停产了，仅俄罗斯有少量生产，大部分你买到的锗管都是拆机下来的、库存货或者假货。</div><div data-resizable="" class="img-dark" style="display: block; margin: 16px auto; resize: both; max-width: 100%; min-width: 40px; min-height: 20px;"><img src="data:image/png;base64," style="pointer-events: none;"></div><br></div>
<p></p>', '基础电子元件库', 0, 1783837718105);
